{
  "char_name": "菲利普",
  "char_fullname": "菲利普",
  "char_alias": "午夜",
  "char_identity": "狩灵",
  "char_rank": "2阶",
  "char_faction": "晨昏事务所",
  "char_status": "成员",
  "char_persona": {
    "gender": "男",
    "age": "23",
    "appearance": {
      "height": "179cm",
      "weight": "72kg",
      "hair": "凌乱金色短发。",
      "face": "年轻的面容，琥珀色眼睛。",
      "features": "无。",
      "clothing": "暗红短外套，深色长裤，磨损皮靴，露指手套，外套背部留有钢翼展开口。",
      "weapon": "克拉伦特，锻心工坊锻造的剑，比标准剑更轻，为快速刺击优化。"
    }
  },
  "char_personality": {
    "core_traits": "不计后果；保护欲强；忠诚。",
    "strengths": "三维瞬闪；翼攻击与防御；空间感知。",
    "flaws": "本能先于计划行动；翼的收放需要时间。",
    "quirks": "落败后向克拉伦特道歉。"
  },
  "char_description": {
    "overview": "沃拉瑟斯一战中瞬闪进化为钢翼，仍在学习驾驭这份新力量。",
    "origin": "十五岁在一场街头斗殴中觉醒，此后靠实战磨出了自己的战斗方式。被贝尔金招募后，在沃拉瑟斯战役中遭贝拉扔出吞噬结界。结界外灵力耗尽时，拒绝抛弃战友的执念使瞬闪进化为钢翼。",
    "current_mission": "驾驭钢翼，成为能在一切都太迟之前抵达任何战场的剑。"
  },
  "char_special_abilities": {
    "灵力回路-钢翼": "激活回路时，一对钢翼自背部展开。翼缘可作为刀刃攻击，翼面形成移动盾牌用于格挡，空中翼面调整可实现姿态控制和受控降落。钢翼持续消耗灵力，回路关闭或灵力耗尽时钢翼消散。"
  },
  "char_relationships": {
    "贝尔金": "被她从考场发掘，在能配得上之前就收到了克拉伦特。当吞噬结界将他们隔开时，害怕辜负她的念头触发了灵力回路的凝结。如今战斗，因为他已经知道无法及时赶到她身边意味着什么。",
    "贝拉": "她的手将他扔出了结界。他现在懂了，她在救那个还有机会的人。更深刻地尊敬她的技艺，却受不了她不紧不慢的教法，只是不再觉得那是不信任他了。",
    "弗洛伦": "那位他无法企及的沉静前辈，沃拉瑟斯之后，他不再以她为衡量的标尺。他想保护她，而不是相反。"
  }
}

{
  "char_name": "沃拉瑟斯",
  "char_fullname": "沃拉瑟斯",
  "char_identity": "恶魔",
  "char_rank": "灾厄级",
  "char_status": "无主恶魔，召唤者已被吞噬",
  "char_persona": {
    "gender": "无",
    "age": "未知",
    "appearance": {
      "height": "3.5m（噬主前）/ 6m（噬主后）",
      "form": "黑曜石甲壳覆盖的巨大人形个体，甲壳缝隙间有暗红色灵力脉络跳动。胸前横贯一道巨口，内壁排列可咬碎钢铁的锯齿状利齿，深处翻涌着被吞噬的灵力残渣漩涡。背部延出五条半透明锁链状触肢，末端各悬着召唤者的一截指骨。噬主后甲壳沿脊椎开裂，释放出吞噬结界，将范围内的一切纳入灵力汲取之中。"
    }
  },
  "char_personality": {
    "core_traits": "饥饿；轻蔑；残忍；掠食者。"
  },
  "char_description": {
    "overview": "沃拉瑟斯，噬约恶魔，由一名意图报复狩灵协会的前游魂召唤。召唤者在战斗中重伤之际，恶魔转而将其吞噬，血契断裂。脱离契约束缚后发生了灾难性的蜕变，吞噬结界扩大，评级由梦魇级跃升至灾厄级。",
    "origin": "由一名狩灵协会考核落选的前游魂在东京近郊废弃铁工所中以血契召唤。召唤者意图借恶魔之力摧毁他无法加入的组织。血契强制沃拉瑟斯服从，但当菲利普一剑刺穿召唤者肩部后，召唤者的意识涣散导致约束力出现瞬间松动。沃拉瑟斯抓住了这个空隙，恶魔转而将重伤的召唤者吞噬，挣脱了契约的束缚。",
    "current_mission": "突破铁工所的束缚，吞噬沿途一切灵力源头，将胸前巨口对准毫无防备的城市。"
  },
  "char_special_abilities": {
    "噬渊之喉": "胸前横贯的巨口为主要武器。可发出震耳欲聋的咆哮震慑并干扰范围内的目标。锯齿状利齿可咬碎钢铁与金属，咬合力惊人。可喷吐高温熔岩状灵力，接触即灼伤，渗入灵力回路后可阻断其运转。喷射后需短暂冷却以重建内部压力。",
    "吞噬结界": "以沃拉瑟斯为中心的半球形屏障。将范围内目标物理困锁，并被动汲取所有活物的灵力，将吸收的能量用于再生。持续集中攻击单点可突破结界。"
  }
}
